#include <bits/stdc++.h>
using namespace std;

int main() {
    const int n = 8;
    string s;
    cin >> s;
    map<char, vector<int>> mp;
    for(int i = 0; i < n; i++) {
        mp[s[i]].push_back(i);
    }
    bool ok = 1;
    ok &= mp['B'][0] % 2 != mp['B'][1] % 2;
    ok &= mp['R'][0] < mp['K'][0] and mp['K'][0] < mp['R'][1];
    cout << (ok ? "Yes\n" : "No\n");
}

fun main() {
  val S = readLine()!!
  val check1 = S.matches(Regex(".*B(..)*B.*")) // Bの位置の偶奇が異なる
  val check2 = S.matches(Regex(".*R.*K.*R.*")) // KがRに挟まれている
  println(if (check1 and check2) "Yes" else "No")
}
